def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'D' if history[0][1] == 'D' else 'C'
    if n >= 98:
        return 'D'

    opp_d = 0
    unprov = 0
    forg = 0
    my_score = 0
    opp_score = 0
    prev_my = None

    for a, b in history:
        if b == 'D':
            opp_d += 1
        if prev_my == 'C' and b == 'D':
            unprov += 1
        if prev_my == 'D' and b == 'C':
            forg += 1

        if a == 'C':
            if b == 'C':
                my_score += 3
                opp_score += 3
            else:
                opp_score += 5
        else:
            if b == 'C':
                my_score += 5
            else:
                my_score += 1
                opp_score += 1

        prev_my = a

    last_a, last_b = history[-1]
    prev_a, prev_b = history[-2]

    dd_streak = 0
    for a, b in reversed(history):
        if a == 'D' and b == 'D':
            dd_streak += 1
        else:
            break

    opp_streak = 0
    for a, b in reversed(history):
        if b == 'D':
            opp_streak += 1
        else:
            break

    coop_rate = (n - opp_d) / float(n)
    hostile = (
        (opp_d >= 3 and opp_d >= n // 2 and n >= 6)
        or (unprov >= 5)
        or (coop_rate < 0.30 and n > 10)
        or (opp_streak >= 5)
    )

    if last_b == 'D' and prev_b == 'D':
        return 'D'

    if last_a == 'C' and last_b == 'D':
        if (
            not hostile
            and prev_a == 'D'
            and prev_b == 'C'
            and unprov <= 3
            and coop_rate > 0.70
            and my_score >= opp_score - 3
        ):
            return 'C'
        return 'D'

    if last_a == 'D' and last_b == 'C':
        if not hostile and prev_a == 'C' and prev_b == 'D' and forg >= 2:
            return 'D'
        if (
            not hostile
            and forg >= 4
            and unprov <= forg
            and coop_rate > 0.60
            and my_score >= opp_score
        ):
            return 'D'
        return 'C'

    if last_a == 'D' and last_b == 'D':
        if not hostile and prev_a == 'D' and prev_b == 'C' and dd_streak <= 3 and unprov <= 3:
            return 'C'
        if (
            not hostile
            and prev_a == 'C'
            and prev_b == 'D'
            and dd_streak <= 2
            and unprov <= 2
            and coop_rate > 0.65
            and my_score >= opp_score - 5
        ):
            return 'C'
        if not hostile and dd_streak >= 4 and coop_rate > 0.45 and my_score >= opp_score - 3:
            return 'C'
        return 'D'

    return 'C'
